[packages/core/src/command/hl7v2-subscriptions/hl7-subscriptions-sftp-ingestion/psv-to-hl7-converter.ts] _⚠️ Potential issue_

**Fix HL7 event coding: wrong trigger values and malformed MSH-9/EVN-1.**

- Enum values use `ADT_A01/ADT_A03`, then MSH-9 becomes `ADT^ADT_A01`—invalid.  
- EVN-1 expects `A01|A03`, not `ADT_A01|ADT_A03`.  
- Trigger selection uses AdmitDateTime to send A03; for discharges use DischargeDateTime.

Apply:

```diff
@@
-enum SUPPORTED_ADT {
-  ADT_A01 = "ADT_A01",
-  ADT_A03 = "ADT_A03",
-}
+enum SUPPORTED_ADT {
+  A01 = "A01",
+  A03 = "A03",
+}
@@
-    const trigger = this.getTriggerEvent(row);
+    const trigger = this.getTriggerEvent(row); // "A01" | "A03"
     const ts = this.getMessageTime(row);
     const mcid = this.getMessageControlId(row);

-    const msh9 = `ADT^${trigger}`;
+    // MSH-9: Message Type = "ADT^A01^ADT_A01" or "ADT^A03^ADT_A03"
+    const msh9 = `ADT^${trigger}^ADT_${trigger}`;
@@
-    const eventType = this.getTriggerEvent(row);
+    const eventType = this.getTriggerEvent(row); // A01 | A03
@@
-  private getTriggerEvent(row: Row): SUPPORTED_ADT {
-    if (row.AdmitDateTime) {
-      console.log(row.AdmitDateTime);
-      return SUPPORTED_ADT.ADT_A03;
-    } else {
-      return SUPPORTED_ADT.ADT_A01;
-    }
-  }
+  private getTriggerEvent(row: Row): SUPPORTED_ADT {
+    // Discharge present => A03, otherwise A01 (admit/visit)
+    return row.DischargeDateTime ? SUPPORTED_ADT.A03 : SUPPORTED_ADT.A01;
+  }
```


