    const gitDir = path.join(absolutePath, ".git");
    if (fs.existsSync(gitDir)) {
      return true;
    }

    const parentDir = path.dirname(absolutePath);
    // Stop recursion when we reach the root directory
    if (parentDir === absolutePath) {
      return false;
    }

    return filePathIsInGitRepository(parentDir);
  } catch (error) {
    // Handle file system access errors gracefully
    return false;
  }
}
