export function makeNameDemographics({
  firstName,
  lastName,
}: {
  firstName: string;
  lastName: string;
}): NameDemographics {
  const firstNamePart = firstName.trim().split(/\s+/);
  const lastNamePart = lastName.trim().split(/\s+/);

  let prefix = "",
    suffix = "";
  if (firstNamePart.length > 1 && isPrefix(firstNamePart[0]?.toLowerCase() ?? "")) {
    prefix = firstNamePart.shift() ?? "";
  }
  if (
    lastNamePart.length > 1 &&
    isSuffix(lastNamePart[lastNamePart.length - 1]?.toLowerCase() ?? "")
  ) {
    suffix = lastNamePart.pop() ?? "";
  }

  let middleName = "";
  let processedFirstName = firstName;
  let processedLastName = lastNamePart.join(" ");
  if (firstNamePart.length > 1) {
    middleName = firstNamePart.slice(1).join(" ");
    processedFirstName = firstNamePart[0] ?? "";
  }

  return {
    firstName: processedFirstName,
    middleName,
    lastName: processedLastName,
    prefix,
    suffix,
  };
}
```

