export function getRequiredValueFromMessage(
  msg: Hl7Message,
  targetSegmentName: string,
  fieldIndex: number,
  componentIndex: number
): string {
  const segment = msg.getSegment(targetSegmentName);
  if (!segment) throw new MetriportError(`Segment ${targetSegmentName} not found in message`);

  const value = getOptionalValueFromSegment(segment, fieldIndex, componentIndex);
  if (!value)
    throw new MetriportError(
      `Required value not found in segment ${targetSegmentName} at field ${fieldIndex}, component ${componentIndex}`
    );

  return value;
}
